package com.ey.cpqadmin.controller;

import com.alibaba.excel.util.StringUtils;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.ey.cpqcommon.common.CommonResult;
import com.ey.cpqcommon.utils.excel.ExcelUtils;
import com.ey.cpqcore.dto.ConfigSolutionDTO;
import com.ey.cpqcore.dto.MaterialNumberMatchDTO;
import com.ey.cpqcore.dto.MaterialPriceCalcDTO;
import com.ey.cpqcore.dto.query.ConfigSolutionQueryDTO;
import com.ey.cpqcore.dto.query.MaterialNumberMatchQueryDTO;
import com.ey.cpqcore.relation.RelationUtil;
import com.ey.cpqcore.service.SolutionMaterialNumberService;
import com.ey.cpqcore.vo.ConfigSolutionExcelVO;
import com.ey.cpqcore.vo.ConfigSolutionVO;
import com.ey.cpqcore.vo.MaterialNumberMatchExcelVO;
import com.ey.cpqcore.vo.MaterialNumberMatchVO;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import javax.servlet.http.HttpServletResponse;
import java.util.Arrays;
import java.util.List;

/**
 * 前端控制器
 *
 * @author author
 * @since 2024年11月14日
 */
@RestController
@RequestMapping("/cpq/admin/solutionMaterialNumber")
@Slf4j
public class MaterialNumberMatchController {

    @Autowired
    private SolutionMaterialNumberService solutionMaterialNumberService;
    @PostMapping("/match")
    public CommonResult matchAndSave(){
        log.info("MaterialNumberMatchController.match.running");
        solutionMaterialNumberService.matchAndSave();
        return CommonResult.success();
    }

    @PostMapping("/getDataListByPage")
    public CommonResult<IPage<MaterialNumberMatchVO>> getDataListByPage(@RequestBody MaterialNumberMatchQueryDTO queryDto) {

        return CommonResult.success(solutionMaterialNumberService.getDataListByPage(queryDto));
    }

    @PostMapping("/download")
    public void download(@RequestBody MaterialNumberMatchDTO queryDto, HttpServletResponse response) {

        List<MaterialNumberMatchExcelVO> exportList = solutionMaterialNumberService.download(queryDto);
        RelationUtil.processResultObject(exportList, "zh-CN");
        ExcelUtils.writeExcel(ConfigSolutionExcelVO.TEMPLATE_NAME, MaterialNumberMatchExcelVO.class, response, exportList);
    }

    /**
     * 价格同步
     * @param resultDto
     * @return
     */
    @PostMapping("/calc/price")
    public CommonResult calcPrice(@RequestBody MaterialPriceCalcDTO resultDto){
        log.info("MaterialNumberMatchController.calcPrice:{}",resultDto);
        List<String> solutionIds = null;
        if(resultDto != null && StringUtils.isNotBlank(resultDto.getSolutionIds())) {
            solutionIds = Arrays.asList(resultDto.getSolutionIds().split(","));
        }
        solutionMaterialNumberService.calcMaterialNumberPrice(solutionIds);
        return CommonResult.success();
    }
}

