112	    @Override
113	    @Transactional(rollbackFor = Exception.class)
114	    public void calcMaterialNumberPrice(List<String> solutionIds) {
115	        //查询所有有效的待确认的配置方案ID集合,不包含小型机
116	        LambdaQueryWrapper<ConfigSolution> wrapper = Wrappers.lambdaQuery(ConfigSolution.class)
117	                .eq(ConfigSolution::getFormStatus, FormStatusEnum.EFFECTIVE.getCode())
118	                .eq(ConfigSolution::getEnableStatus, EnableStatusEnum.ENABLE.getCode())
119	                .ne(ConfigSolution::getProductLineId, ProductLineType.COMPLEX_MACHINERY.getProductLineId());
120	        if (CollUtil.isNotEmpty(solutionIds)) {
121	            wrapper.in(ConfigSolution::getSolutionId, solutionIds);
122	        }
123	        List<ConfigSolution> solutionInfos = configSolutionService.list(wrapper);
124	        if (CollUtil.isEmpty(solutionInfos)) {
125	            log.info("solutionIds:{},没有找到配置方案！", solutionIds);
126	            return;
127	        }
128	        //循环配置方案ID，获取对应匹配的物料号
129	        TimeInterval timer = new TimeInterval();
130	        timer.start();
131	        List<SolutionMaterialNumber> solutionMaterialNumbers = new ArrayList<>();
132	        for (ConfigSolution solutionInfo : solutionInfos) {
133	            //获取配置方案匹配到得的物料号集合
134	            List<String> materialNumbers = getMatchedMaterialNumber(solutionInfo, null);
135	            if (CollUtil.isEmpty(materialNumbers)) {
136	                continue;
137	            }
138	            log.info("配置方案：{} 匹配的物料号集合：{}", solutionInfo.getSolutionId(), materialNumbers);
139	            buildSolutionMaterialNumberList(solutionInfo, solutionMaterialNumbers, materialNumbers);
140	        }
141	        long matchCost = timer.interval(); // 获取第一段耗时
142	        log.info("配置方案匹配物料号耗时：{}毫秒", matchCost);
143	        if (CollUtil.isEmpty(solutionMaterialNumbers)) {
144	            return;
145	        }
146	        log.info("需计算物料号价格的条数{}", solutionMaterialNumbers.size());
147	        //根据方案匹配的物料号计算价格
148	        timer.restart();
149	        List<MaterialPrice> materialPrices = calcMaterialPrice(solutionMaterialNumbers);
150	        long calcPriceCost = timer.interval();
151	        log.info("计算物料号价格耗时：{}毫秒", calcPriceCost);
152	        //批量保存配置方案和物料号价格数据
153	        if (CollUtil.isNotEmpty(materialPrices)) {
154	            //传指定配置方案来匹配并计算价格时， 不清空表数据
155	            if (CollUtil.isEmpty(solutionIds)) {
156	                materialPriceService.remove(Wrappers.lambdaQuery(MaterialPrice.class));
157	                materialPriceCalcService.remove(Wrappers.lambdaQuery(MaterialPriceCalc.class));
158	            }
159	            for (MaterialPrice materialPrice : materialPrices) {
160	                List<MaterialPriceCalc> calcList = materialPrice.getCalcList();
161	                materialPriceService.save(materialPrice);
162	                if (CollUtil.isNotEmpty(calcList)) {
163	                    calcList.forEach(item -> item.setMaterialPriceId(materialPrice.getId()));
164	                    materialPriceCalcService.saveBatch(calcList);
165	                }
166	            }
167	            if (CollUtil.isNotEmpty(solutionIds)) {
168	                //发布推送价格数据到MQ的事件
169	                applicationEventPublisher.publishEvent(new SendMaterialPriceEvent(materialPrices, UserContext.getUser()));
170	            }
171	        }
172	
173	        //批量保存配置方案和物料号匹配数据
174	        /*if(CollUtil.isNotEmpty(solutionMaterialNumbers)) {
175	            //传指定配置方案来匹配并计算价格时， 不清空表数据
176	            if(CollUtil.isEmpty(solutionIds)) {
177	                remove(Wrappers.lambdaQuery(SolutionMaterialNumber.class));
178	            }
179	            saveBatch(solutionMaterialNumbers);
180	        }*/
181	    }
182	
183	    /**
184	     * 物料价格计算
185	     *
186	     * @param solutionMaterialNumbers
187	     * @return
188	     */
189	    private List<MaterialPrice> calcMaterialPrice(List<SolutionMaterialNumber> solutionMaterialNumbers) {
190	        List<MaterialPrice> materialPrices = solutionMaterialNumbers.parallelStream()
191	                .flatMap(solutionMaterialNumber -> {
192	                    TimeInterval timer = new TimeInterval();
193	                    timer.restart();
194	                    List<MaterialPrice> subMaterialPrices = portalRelationService.calcSolutionMaterialPrice(solutionMaterialNumber);
195	                    log.info("配置方案：{},物料号：{},物料价格：{}",solutionMaterialNumber.getSolutionId(),solutionMaterialNumber.getMaterialNumber(), JSONUtil.toJsonStr(subMaterialPrices));
196	                    log.info("配置方案：{} 匹配物料号：{} 耗时：{}毫秒",solutionMaterialNumber.getSolutionId(),solutionMaterialNumber.getMaterialNumber(),timer.interval());
197	                    return CollUtil.isEmpty(subMaterialPrices)? Stream.empty():subMaterialPrices.stream();
198	                })
199	                .collect(Collectors.toList());
200	
201	        return materialPrices;
202	    }
203	
204	
205	    /**
206	     * 构建配置方案和物料号匹配数据
207	     *
208	     * @param solutionInfo
209	     * @param solutionMaterialNumbers
210	     * @param materialNumbers
211	     */
212	    private static void buildSolutionMaterialNumberList(ConfigSolution solutionInfo, List<SolutionMaterialNumber> solutionMaterialNumbers, List<String> materialNumbers) {
213	        //封装创建数据
214	        solutionMaterialNumbers.addAll(materialNumbers.stream().map(materialNumber -> {
215	            SolutionMaterialNumber solutionMaterialNumber = new SolutionMaterialNumber();
216	            solutionMaterialNumber.setSolutionId(solutionInfo.getSolutionId());
217	            solutionMaterialNumber.setMaterialNumber(materialNumber);
218	            solutionMaterialNumber.setProductLineId(solutionInfo.getProductLineId());
219	            solutionMaterialNumber.setModelId(solutionInfo.getModelId());
220	            solutionMaterialNumber.setFormStatus(solutionInfo.getFormStatus());
221	            return solutionMaterialNumber;
222	        }).collect(Collectors.toList()));
223	    }
224	
225	    /**
226	     * 根据配置方案获取配置方案匹配的物料号集合
227	     *
228	     * @param solutionInfo
229	     * @param materialNumbers
230	     * @return
231	     */
232	    @Override
233	    public List<String> getMatchedMaterialNumber(ConfigSolution solutionInfo, Collection<String> materialNumbers) {
234	        //获取配置方案相关数据
235	        SolutionRelationDataVo solutionRelationData = getSolutionRelationData(solutionInfo);
236	        if (solutionRelationData == null) {
237	            log.info("配置方案：{} 相关数据异常", solutionInfo.getSolutionId());
238	            return null;
239	        }
240	        //获取配置方案同机型的所有可售物料号
241	        List<SaleMaterial> saleMaterials = null;
242	        if (CollUtil.isNotEmpty(materialNumbers)) {
243	            saleMaterials = saleMaterialService.list(Wrappers.lambdaQuery(SaleMaterial.class).in(SaleMaterial::getMaterialNumber, materialNumbers).eq(SaleMaterial::getState, "1"));
244	        } else {
245	            saleMaterials = saleMaterialService.list(Wrappers.lambdaQuery(SaleMaterial.class).eq(SaleMaterial::getModelId, solutionInfo.getModelId()).eq(SaleMaterial::getState, "1"));
246	        }
247	        if (CollUtil.isEmpty(saleMaterials)) {
248	            log.info("配置方案：{} 同机型下无可售物料号", solutionInfo.getSolutionId());
249	            return null;
250	        }
251	        //获取物料号与配置项ID集合映射
252	        Map<String, Set<String>> materialOptionMap = getMaterialOptionMap(saleMaterials);
253	        //匹配结果
254	        List<String> matchedMaterialNumbers = new ArrayList<>();
255	        for (Map.Entry<String, Set<String>> materialOptionEntry : materialOptionMap.entrySet()) {
256	            Set<String> materialOptionValueIds = materialOptionEntry.getValue();
257	            //校验配置方案是否能匹配物料号
258	            if (checkSolutionMatchMaterial(solutionRelationData, materialOptionValueIds, materialOptionEntry.getKey())) {
259	                matchedMaterialNumbers.add(materialOptionEntry.getKey());
260	            }
261	        }
262	        return matchedMaterialNumbers;
263	    }
264	
265	    /**
266	     * 校验配置方案是否能匹配物料号
267	     *
268	     * @param solutionRelationData
269	     * @param materialOptionValueIds
270	     * @param materialNumber
271	     * @return
272	     */
273	    private boolean checkSolutionMatchMaterial(SolutionRelationDataVo solutionRelationData, Set<String> materialOptionValueIds, String materialNumber) {
274	        //待选择的配置项（当没有值时，证明在此配置方案都可选择出此物料号下的所有配置项）
275	        Set<String> pendingSelectionMaterialOptions = new HashSet<>(materialOptionValueIds);
276	        log.info("配置方案：{},物料号：{}, 待选择的配置项：{},开始匹配", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
277	        //基本配置校验物料号是否满足
278	        if (!checkStatic(solutionRelationData, pendingSelectionMaterialOptions)) {
279	            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},基本配置校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
280	            return false;
281	        }
282	        //检查营销不可见的配置项是否满足
283	        if (CollUtil.isNotEmpty(solutionRelationData.getNoSaleNeedOptionValueIds()) && !pendingSelectionMaterialOptions.containsAll(solutionRelationData.getNoSaleNeedOptionValueIds())) {
284	            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},营销不可见的配置项校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
285	            return false;
286	        }
287	        if (CollUtil.isNotEmpty(solutionRelationData.getNoSaleNeedOptionValueIds()) && pendingSelectionMaterialOptions.containsAll(solutionRelationData.getNoSaleNeedOptionValueIds())) {
288	            solutionRelationData.getNoSaleNeedOptionValueIds().forEach(pendingSelectionMaterialOptions::remove);
289	        }
290	        //必选配置校验物料号是否满足
291	        if (!checkMust(solutionRelationData, pendingSelectionMaterialOptions)) {
292	            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},必选配置校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
293	            return false;
294	        }
295	        //可选配置校验物料号是否满足
296	        checkOptional(solutionRelationData, pendingSelectionMaterialOptions);
297	        //如果待选择的配置项不为空，则返回false
298	        log.info("配置方案id:{},物料号：{},待选择的配置项：{}", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
299	        return !CollUtil.isNotEmpty(pendingSelectionMaterialOptions);
300	    }
301	
302	    /**
303	     * 可选配置校验物料号是否满足
304	     *
305	     * @param solutionRelationData
306	     * @param pendingSelectionMaterialOptions
307	     * @return
308	     */
309	    private void checkOptional(SolutionRelationDataVo solutionRelationData, Set<String> pendingSelectionMaterialOptions) {
310	        List<ConfigCatalog> optionalCatalogList = solutionRelationData.getOptionalCatalogList();
311	        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
312	        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
313	        //配置组合和其配置项的映射
314	        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
315	        //如果可选项为空 且 待选择的配置项不为空，则返回false不匹配
316	        if (CollUtil.isEmpty(optionalCatalogList) && CollUtil.isNotEmpty(pendingSelectionMaterialOptions)) {
317	            return;
318	        }
319	        for (ConfigCatalog configCatalog : optionalCatalogList) {
320	            //分类下关联的配置项数据
321	            List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(configCatalog.getId());
322	            //分类下关联的配置组合数据
323	            List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(configCatalog.getId());
324	            //如果本分类没有配置项和配置组合数据，跳过本配置分类的校验（多级配置分类情况）
325	            if (CollUtil.isEmpty(configCatalogGroups) && CollUtil.isEmpty(configCatalogValues)) {
326	                continue;
327	            }
328	            if (SelectTypeEnum.SINGLE.getCode().equals(configCatalog.getSelectType())) {
329	                //单选匹配逻辑
330	                optionalSingleMatch(pendingSelectionMaterialOptions, configCatalogGroups, groupValueMapping, configCatalogValues);
331	            } else {
332	                //多选匹配
333	                optionalMutiMatch(pendingSelectionMaterialOptions, configCatalogValues, configCatalogGroups, groupValueMapping);
334	            }
335	        }
336	    }
337	
338	    /**
339	     * 可选配置多选匹配逻辑
340	     *
341	     * @param pendingSelectionMaterialOptions
342	     * @param configCatalogValues
343	     * @param configCatalogGroups
344	     * @param groupValueMapping
345	     */
346	    private static void optionalMutiMatch(Set<String> pendingSelectionMaterialOptions, List<ConfigCatalogValue> configCatalogValues, List<ConfigCatalogGroup> configCatalogGroups, Map<String, Set<String>> groupValueMapping) {
347	        //配置组合匹配（已在数据来源处按配置项数量降序排序）
348	        if (CollUtil.isNotEmpty(configCatalogGroups)) {
349	            for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
