534	        List<ConfigCatalog> staticCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.STATIC.getCode())).collect(Collectors.toList());
535	        //获取配置方案必选所有分类
536	        List<ConfigCatalog> mustCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.MUST.getCode())).collect(Collectors.toList());
537	        //获取配置方案可选所有分类
538	        List<ConfigCatalog> optionalCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.OPTIONAL.getCode())).collect(Collectors.toList());
539	        List<Long> allCatalogIds = configCatalogList.stream().map(ConfigCatalog::getId).collect(Collectors.toList());
540	        //获取所有配置分类下和配置项集合的映射
541	        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = configCatalogValueService.list(Wrappers.lambdaQuery(ConfigCatalogValue.class).in(ConfigCatalogValue::getCatalogId, allCatalogIds)).stream().collect(Collectors.groupingBy(
542	                ConfigCatalogValue::getCatalogId
543	        ));
544	        //获取所有配置分类下和配置组合集合的映射
545	        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = configCatalogGroupService.list(Wrappers.lambdaQuery(ConfigCatalogGroup.class).in(ConfigCatalogGroup::getCatalogId, allCatalogIds)).stream().collect(Collectors.groupingBy(
546	                ConfigCatalogGroup::getCatalogId
547	        ));
548	        //配置组合ID集合
549	        Set<String> allGroupIds = new HashSet<>();
550	        //配置组合ID和配置项的映射
551	        Map<String, Set<String>> groupValueMapping = new HashMap<>();
552	        if (!catalogGroupMapping.isEmpty()) {
553	            allGroupIds = catalogGroupMapping.values().stream().flatMap(List::stream).map(ConfigCatalogGroup::getGroupId).collect(Collectors.toSet());
554	            //设置配置组合ID和配置项的映射
555	            setGroupValueMapping(allGroupIds, groupValueMapping);
556	        }
557	        //查询营销不可见的配置项ID集合
558	        List<String> noSaleNeedOptionValueIds = new ArrayList<>();
559	        List<SaleMaterialOptionValueVO> saleMaterialOptionValueVOList = saleMaterialMapper.queryMaterialOptionValuesNoNeed(solutionInfo.getMaterialNumber());
560	        if (CollUtil.isNotEmpty(saleMaterialOptionValueVOList)) {
561	            List<String> optionValueIdList = saleMaterialOptionValueVOList.stream().map(SaleMaterialOptionValueVO::getOptionValueId).collect(Collectors.toList());
562	            if (CollUtil.isNotEmpty(optionValueIdList)) {
563	                noSaleNeedOptionValueIds.addAll(optionValueIdList);
564	            }
565	        }
566	        //组装参数返回
567	        solutionRelationDataVo.setConfigCatalogList(configCatalogList);
568	        solutionRelationDataVo.setAllCatalogIds(allCatalogIds);
569	        solutionRelationDataVo.setStaticCatalogList(staticCatalogList);
570	        solutionRelationDataVo.setSolutionId(solutionInfo.getSolutionId());
571	        solutionRelationDataVo.setMustCatalogList(mustCatalogList);
572	        solutionRelationDataVo.setOptionalCatalogList(optionalCatalogList);
573	        solutionRelationDataVo.setCatalogValueMapping(catalogValueMapping);
574	        // 对catalogGroupMapping中每个配置分类下的配置组合列表按配置项数量降序排序
575	        Map<Long, List<ConfigCatalogGroup>> sortedCatalogGroupMapping = sortCatalogGroupMappingByGroupSize(catalogGroupMapping, groupValueMapping);
576	        solutionRelationDataVo.setCatalogGroupMapping(sortedCatalogGroupMapping);
577	        solutionRelationDataVo.setGroupValueMapping(groupValueMapping);
578	        solutionRelationDataVo.setAllGroupIds(allGroupIds);
579	        solutionRelationDataVo.setNoSaleNeedOptionValueIds(noSaleNeedOptionValueIds);
580	        return solutionRelationDataVo;
581	    }
