583	    /**
584	     * 对配置分类下的配置组合列表按配置组合包含的配置项数量降序排序
585	     * 配置项多的配置组合排在前面，这样可以优先匹配大的配置组合，最大化排除pendingSelectionMaterialOptions
586	     *
587	     * @param catalogGroupMapping 配置分类和配置组合的映射
588	     * @param groupValueMapping   配置组合和配置项的映射
589	     * @return 排序后的映射
590	     */
591	    private Map<Long, List<ConfigCatalogGroup>> sortCatalogGroupMappingByGroupSize(
592	            Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping,
593	            Map<String, Set<String>> groupValueMapping) {
594	        Map<Long, List<ConfigCatalogGroup>> sortedMapping = new HashMap<>();
595	        for (Map.Entry<Long, List<ConfigCatalogGroup>> entry : catalogGroupMapping.entrySet()) {
596	            Long catalogId = entry.getKey();
597	            List<ConfigCatalogGroup> groups = entry.getValue();
598	            if (CollUtil.isNotEmpty(groups)) {
599	                // 按配置组合拥有的配置项数量降序排序
600	                List<ConfigCatalogGroup> sortedGroups = groups.stream()
601	                        .sorted((g1, g2) -> {
602	                            Set<String> ids1 = groupValueMapping.get(g1.getGroupId());
603	                            Set<String> ids2 = groupValueMapping.get(g2.getGroupId());
604	                            int size1 = ids1 != null ? ids1.size() : 0;
605	                            int size2 = ids2 != null ? ids2.size() : 0;
606	                            return Integer.compare(size2, size1); // 降序排序
607	                        })
608	                        .collect(Collectors.toList());
609	                sortedMapping.put(catalogId, sortedGroups);
610	            } else {
611	                sortedMapping.put(catalogId, groups);
612	            }
613	        }
614	        return sortedMapping;
615	    }
