685	    /**
686	     * 根据物料号反向获取匹配的配置方案ID列表
687	     *
688	     * @param materialNumber 物料号
689	     * @param country        国家（可选，用于过滤配置方案适用范围）
690	     * @return 匹配的配置方案ID列表
691	     */
692	    @Override
693	    public List<String> getMatchedSolutionIds(String materialNumber, String country) {
694	        // 查询物料号基本信息
695	        SaleMaterial saleMaterial = saleMaterialService.getSaleMaterialByNumber(materialNumber);
696	        if (saleMaterial == null) {
697	            log.info("物料号：{} 不存在", materialNumber);
698	            return null;
699	        }
700	        // 查询该机型下所有生效的配置方案
701	        List<ConfigSolution> solutionList = configSolutionService.list(
702	                Wrappers.lambdaQuery(ConfigSolution.class)
703	                        .eq(ConfigSolution::getModelId, saleMaterial.getModelId())
704	                        .eq(ConfigSolution::getFormStatus, FormStatusEnum.EFFECTIVE.getCode())
705	                        .ne(ConfigSolution::getProductLineId, ProductLineType.COMPLEX_MACHINERY.getProductLineId())
706	        );
707	        if (CollUtil.isEmpty(solutionList)) {
708	            log.info("物料号：{} 同机型下没有生效的配置方案", materialNumber);
709	            return null;
710	        }
711	        // 如果指定了国家，则根据配置方案的适用范围过滤
712	        if (StringUtils.isNotBlank(country)) {
713	            // 查询所有方案的国家适用范围
714	            List<String> solutionIds = solutionList.stream().map(ConfigSolution::getSolutionId).collect(Collectors.toList());
715	            List<ConfigSolutionScope> scopeList = configSolutionScopeService.list(
716	                    Wrappers.lambdaQuery(ConfigSolutionScope.class)
717	                            .in(ConfigSolutionScope::getSolutionId, solutionIds)
718	                            .eq(ConfigSolutionScope::getCountry, country)
719	            );
720	            // 获取符合国家范围的方案ID集合
721	            Set<String> validSolutionIds = scopeList.stream().map(ConfigSolutionScope::getSolutionId).collect(Collectors.toSet());
722	            // 过滤方案列表
723	            solutionList = solutionList.stream()
724	                    .filter(solution -> validSolutionIds.contains(solution.getSolutionId()))
725	                    .collect(Collectors.toList());
726	            if (CollUtil.isEmpty(solutionList)) {
727	                log.info("物料号：{} 同机型下没有适用于国家 {} 的配置方案", materialNumber, country);
728	                return null;
729	            }
730	        }
731	        // 获取物料号关联的配置项ID集合
732	        Set<String> materialOptionValueIds = getMaterialOptionValueIds(materialNumber);
733	        if (CollUtil.isEmpty(materialOptionValueIds)) {
734	            log.info("物料号：{} 没有关联的配置项", materialNumber);
735	            return null;
736	        }
737	        // 遍历配置方案，判断物料号是否匹配
738	        List<String> matchedSolutionIds = new ArrayList<>();
739	        for (ConfigSolution solution : solutionList) {
740	            // 获取配置方案相关数据
741	            SolutionRelationDataVo solutionRelationData = getSolutionRelationData(solution);
742	            if (solutionRelationData == null) {
743	                continue;
744	            }
745	            // 校验是否匹配
746	            if (checkSolutionMatchMaterial(solutionRelationData, new HashSet<>(materialOptionValueIds), materialNumber)) {
747	                matchedSolutionIds.add(solution.getSolutionId());
748	            }
749	        }
750	        return matchedSolutionIds;
751	    }
