812	     * @param solutionRelationData   配置方案相关数据
813	     * @param materialOptionValueIds 物料号配置项ID集合
814	     * @param solution               配置方案
815	     * @return 匹配关系VO
816	     */
817	    private MaterialNumberMatchRelationVO buildMatchRelationVO(SolutionRelationDataVo solutionRelationData,
818	                                                               Set<String> materialOptionValueIds, ConfigSolution solution) {
819	        MaterialNumberMatchRelationVO relationVO = new MaterialNumberMatchRelationVO();
820	        relationVO.setSolutionId(solution.getSolutionId());
821	        relationVO.setMaterialNumber(solution.getMaterialNumber());
822	        relationVO.setModelId(solution.getModelId());
823	
824	        // 获取基本配置项ID集合
825	        Set<String> staticOptionValueIds = getStaticOptionValueIds(solutionRelationData);
826	        relationVO.setStaticOptionValueIds(staticOptionValueIds);
827	
828	        // 获取NC配置项ID集合和有NC项的分类ID集合（后续会过滤）
829	        Set<Long> catalogIdsWithNc = new HashSet<>();
830	        Map<Long, Set<String>> catalogNcOptionValueIds = new HashMap<>();
831	        Set<String> ncOptionValueIds = getNcOptionValueIdsAndCatalogIds(solutionRelationData,
832	                catalogIdsWithNc, catalogNcOptionValueIds);
833	        relationVO.setNcOptionValueIds(ncOptionValueIds);
834	
835	        // 获取匹配的配置组合ID集合和groupId到catalogId的映射
836	        Map<String, Long> groupCatalogMapping = new HashMap<>();
837	        Set<String> matchedGroupIds = getMatchedGroupIdsWithCatalogMapping(solutionRelationData,
838	                materialOptionValueIds, groupCatalogMapping);
839	        relationVO.setGroupIds(matchedGroupIds);
840	        relationVO.setGroupCatalogMapping(groupCatalogMapping);
841	
842	        // 获取匹配的配置项ID集合和optionValueId到catalogId的映射
843	        Map<String, Long> optionValueCatalogMapping = new HashMap<>();
844	        Set<String> matchedOptionValueIds = new HashSet<>();
845	        buildMatchedOptionValueIds(solutionRelationData, materialOptionValueIds, staticOptionValueIds,
846	                ncOptionValueIds, matchedGroupIds, matchedOptionValueIds, optionValueCatalogMapping);
847	        relationVO.setOptionValueIds(matchedOptionValueIds);
848	        relationVO.setOptionValueCatalogMapping(optionValueCatalogMapping);
849	
850	        // 过滤catalogIdsWithNc：只保留有NC项但物料号不包含该分类下NC项的分类
851	        // 如果物料号包含该分类下的NC项，则该分类不需要减去NC项价格
852	        filterCatalogIdsWithNc(catalogIdsWithNc, catalogNcOptionValueIds, materialOptionValueIds,
853	                matchedGroupIds, matchedOptionValueIds, groupCatalogMapping, optionValueCatalogMapping);
854	        relationVO.setCatalogIdsWithNc(catalogIdsWithNc);
855	
856	        return relationVO;
857	    }
858	
859	    /**
860	     * 过滤catalogIdsWithNc：只保留需要减去NC项价格的分类
861	     * 规则：分类有NC项，物料号匹配了该分类下的非NC项，但物料号不包含该分类下的NC项
862	     *
863	     * @param catalogIdsWithNc          有NC项的分类ID集合（输入输出参数）
864	     * @param catalogNcOptionValueIds   每个分类的NC项ID集合
865	     * @param materialOptionValueIds    物料号原始配置项ID集合
866	     * @param matchedGroupIds           匹配的配置组合ID集合
867	     * @param matchedOptionValueIds     匹配的配置项ID集合
868	     * @param groupCatalogMapping       配置组合到分类的映射
869	     * @param optionValueCatalogMapping 配置项到分类的映射
870	     */
871	    private void filterCatalogIdsWithNc(Set<Long> catalogIdsWithNc, Map<Long, Set<String>> catalogNcOptionValueIds,
872	                                        Set<String> materialOptionValueIds, Set<String> matchedGroupIds, Set<String> matchedOptionValueIds,
873	                                        Map<String, Long> groupCatalogMapping, Map<String, Long> optionValueCatalogMapping) {
874	        // 收集物料号匹配的分类ID集合（匹配了非NC项的分类）
875	        Set<Long> matchedCatalogIds = new HashSet<>();
876	        if (CollUtil.isNotEmpty(matchedGroupIds)) {
877	            for (String groupId : matchedGroupIds) {
878	                Long catalogId = groupCatalogMapping.get(groupId);
879	                if (catalogId != null) {
880	                    matchedCatalogIds.add(catalogId);
881	                }
882	            }
883	        }
884	        if (CollUtil.isNotEmpty(matchedOptionValueIds)) {
885	            for (String optionValueId : matchedOptionValueIds) {
886	                Long catalogId = optionValueCatalogMapping.get(optionValueId);
887	                if (catalogId != null) {
888	                    matchedCatalogIds.add(catalogId);
889	                }
890	            }
891	        }
892	
893	        // 过滤catalogIdsWithNc：只保留满足条件的分类
894	        Set<Long> filteredCatalogIdsWithNc = new HashSet<>();
895	        for (Long catalogId : catalogIdsWithNc) {
896	            // 条件1：物料号匹配了该分类下的非NC项（分类在matchedCatalogIds中）
897	            if (!matchedCatalogIds.contains(catalogId)) {
898	                continue;
899	            }
900	            // 条件2：物料号不包含该分类下的NC项
901	            Set<String> ncIds = catalogNcOptionValueIds.get(catalogId);
902	            if (CollUtil.isNotEmpty(ncIds)) {
903	                boolean materialContainsNc = false;
904	                for (String ncId : ncIds) {
905	                    if (materialOptionValueIds.contains(ncId)) {
906	                        materialContainsNc = true;
907	                        break;
908	                    }
909	                }
910	                // 如果物料号包含该分类下的NC项，则不需要减去NC项价格
911	                if (materialContainsNc) {
912	                    continue;
913	                }
914	            }
915	            // 满足条件：该分类需要减去NC项价格
916	            filteredCatalogIdsWithNc.add(catalogId);
917	        }
918	        catalogIdsWithNc.clear();
919	        catalogIdsWithNc.addAll(filteredCatalogIdsWithNc);
920	    }
921	
922	    /**
923	     * 获取基本配置项ID集合
924	     *
925	     * @param solutionRelationData 配置方案相关数据
926	     * @return 基本配置项ID集合
927	     */
928	    private Set<String> getStaticOptionValueIds(SolutionRelationDataVo solutionRelationData) {
929	        Set<String> staticOptionValueIds = new HashSet<>();
930	        List<ConfigCatalog> staticCatalogList = solutionRelationData.getStaticCatalogList();
931	        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
932	        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
933	        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
934	
935	        if (CollUtil.isNotEmpty(staticCatalogList)) {
936	            for (ConfigCatalog staticCatalog : staticCatalogList) {
937	                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(staticCatalog.getId());
938	                if (CollUtil.isNotEmpty(configCatalogValues)) {
939	                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
940	                        if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup())) {
941	                            staticOptionValueIds.add(configCatalogValue.getOptionValueId());
942	                        }
943	                    }
944	                }
945	                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(staticCatalog.getId());
946	                if (CollUtil.isNotEmpty(configCatalogGroups)) {
947	                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
948	                        Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
949	                        if (CollUtil.isNotEmpty(optionValueIds)) {
950	                            staticOptionValueIds.addAll(optionValueIds);
951	                        }
952	                    }
953	                }
954	            }
955	        }
956	        return staticOptionValueIds;
957	    }
958	
959	    /**
960	     * 获取NC配置项ID集合和有NC项的分类ID集合
961	     *
962	     * @param solutionRelationData    配置方案相关数据
963	     * @param catalogIdsWithNc        有NC项的分类ID集合（输出参数，后续会过滤）
964	     * @param catalogNcOptionValueIds 每个分类的NC项ID集合（输出参数）
965	     * @return NC配置项ID集合
966	     */
967	    private Set<String> getNcOptionValueIdsAndCatalogIds(SolutionRelationDataVo solutionRelationData,
968	                                                         Set<Long> catalogIdsWithNc, Map<Long, Set<String>> catalogNcOptionValueIds) {
969	        Set<String> ncOptionValueIds = new HashSet<>();
970	        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
971	        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
972	        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
973	        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
974	
975	        // 排除基本配置分类
976	        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
977	                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
978	                .collect(Collectors.toList());
979	
980	        if (CollUtil.isNotEmpty(otherCatalogList)) {
981	            for (ConfigCatalog catalog : otherCatalogList) {
982	                Set<String> catalogNcIds = new HashSet<>();
983	                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(catalog.getId());
984	                if (CollUtil.isNotEmpty(configCatalogValues)) {
985	                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
986	                        if ("1".equals(configCatalogValue.getOptionValueNc())) {
987	                            ncOptionValueIds.add(configCatalogValue.getOptionValueId());
988	                            catalogNcIds.add(configCatalogValue.getOptionValueId());
989	                        }
990	                    }
991	                }
992	                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(catalog.getId());
993	                if (CollUtil.isNotEmpty(configCatalogGroups)) {
994	                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
995	                        if ("1".equals(configCatalogGroup.getGroupNc())) {
996	                            Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
997	                            if (CollUtil.isNotEmpty(optionValueIds)) {
998	                                ncOptionValueIds.addAll(optionValueIds);
999	                                catalogNcIds.addAll(optionValueIds);
1000	                            }
1001	                        }
1002	                    }
1003	                }
1004	                // 记录有NC项的分类ID和该分类的NC项ID集合
1005	                if (!catalogNcIds.isEmpty()) {
1006	                    catalogIdsWithNc.add(catalog.getId());
1007	                    catalogNcOptionValueIds.put(catalog.getId(), catalogNcIds);
1008	                }
1009	            }
1010	        }
1011	        return ncOptionValueIds;
1012	    }
1013	
1014	    /**
1015	     * 获取匹配的配置组合ID集合和groupId到catalogId的映射
1016	     *
1017	     * @param solutionRelationData   配置方案相关数据
1018	     * @param materialOptionValueIds 物料号配置项ID集合
1019	     * @param groupCatalogMapping    groupId到catalogId的映射（输出参数）
1020	     * @return 匹配的配置组合ID集合
1021	     */
1022	    private Set<String> getMatchedGroupIdsWithCatalogMapping(SolutionRelationDataVo solutionRelationData,
1023	                                                             Set<String> materialOptionValueIds, Map<String, Long> groupCatalogMapping) {
1024	        Set<String> matchedGroupIds = new HashSet<>();
1025	        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
1026	        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
1027	        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
1028	
1029	        // 排除基本配置分类
1030	        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
1031	                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
1032	                .collect(Collectors.toList());
1033	
1034	        if (CollUtil.isNotEmpty(otherCatalogList)) {
1035	            for (ConfigCatalog catalog : otherCatalogList) {
1036	                // 判断是否需要匹配后跳出：必选配置 或 可选配置单选
1037	                boolean shouldBreakOnMatch = ConfigType.MUST.getCode().equals(catalog.getConfigType())
1038	                        || (ConfigType.OPTIONAL.getCode().equals(catalog.getConfigType())
1039	                        && SelectTypeEnum.SINGLE.getCode().equals(catalog.getSelectType()));
1040	                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(catalog.getId());
1041	                if (CollUtil.isNotEmpty(configCatalogGroups)) {
1042	                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
1043	                        // 排除NC配置组合
1044	                        if ("1".equals(configCatalogGroup.getGroupNc())) {
1045	                            continue;
1046	                        }
1047	                        Set<String> groupOptionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
1048	                        if (CollUtil.isNotEmpty(groupOptionValueIds)
1049	                                && materialOptionValueIds.containsAll(groupOptionValueIds)) {
1050	                            matchedGroupIds.add(configCatalogGroup.getGroupId());
1051	                            // 记录groupId到catalogId的映射
1052	                            groupCatalogMapping.put(configCatalogGroup.getGroupId(), catalog.getId());
1053	                            // 必选配置或可选配置单选时，匹配到后结束该分类的匹配
1054	                            if (shouldBreakOnMatch) {
1055	                                break;
1056	                            }
1057	                        }
1058	                    }
1059	                }
1060	            }
1061	        }
1062	        return matchedGroupIds;
1063	    }
1064	
1065	    /**
1066	     * 构建匹配的配置项ID集合和optionValueId到catalogId的映射
1067	     *
1068	     * @param solutionRelationData      配置方案相关数据
1069	     * @param materialOptionValueIds    物料号配置项ID集合
1070	     * @param staticOptionValueIds      基本配置项ID集合
1071	     * @param ncOptionValueIds          NC配置项ID集合
1072	     * @param matchedGroupIds           匹配的配置组合ID集合
1073	     * @param matchedOptionValueIds     匹配的配置项ID集合（输出参数）
1074	     * @param optionValueCatalogMapping optionValueId到catalogId的映射（输出参数）
1075	     */
1076	    private void buildMatchedOptionValueIds(SolutionRelationDataVo solutionRelationData,
1077	                                            Set<String> materialOptionValueIds, Set<String> staticOptionValueIds, Set<String> ncOptionValueIds,
1078	                                            Set<String> matchedGroupIds, Set<String> matchedOptionValueIds,
1079	                                            Map<String, Long> optionValueCatalogMapping) {
1080	        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
1081	        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
1082	        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
1083	
1084	        // 排除基本配置分类
1085	        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
1086	                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
1087	                .collect(Collectors.toList());
1088	
1089	        if (CollUtil.isNotEmpty(otherCatalogList)) {
1090	            for (ConfigCatalog catalog : otherCatalogList) {
1091	                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(catalog.getId());
1092	                if (CollUtil.isNotEmpty(configCatalogValues)) {
1093	                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
1094	                        String optionValueId = configCatalogValue.getOptionValueId();
1095	                        // 排除NC配置项、基本配置项
1096	                        if ("1".equals(configCatalogValue.getOptionValueNc())) {
1097	                            continue;
1098	                        }
1099	                        if (staticOptionValueIds.contains(optionValueId)) {
1100	                            continue;
1101	                        }
1102	                        if (ncOptionValueIds.contains(optionValueId)) {
1103	                            continue;
1104	                        }
1105	                        // 排除已包含在匹配的配置组合中的配置项
1106	                        boolean isInMatchedGroup = false;
1107	                        if (CollUtil.isNotEmpty(matchedGroupIds)) {
1108	                            for (String groupId : matchedGroupIds) {
1109	                                Set<String> groupOptionValueIds = groupValueMapping.get(groupId);
1110	                                if (CollUtil.isNotEmpty(groupOptionValueIds) && groupOptionValueIds.contains(optionValueId)) {
1111	                                    isInMatchedGroup = true;
1112	                                    break;
1113	                                }
1114	                            }
1115	                        }
1116	                        if (isInMatchedGroup) {
1117	                            continue;
1118	                        }
1119	                        // 物料号包含该配置项
1120	                        if (materialOptionValueIds.contains(optionValueId)) {
1121	                            matchedOptionValueIds.add(optionValueId);
1122	                            // 记录optionValueId到catalogId的映射
1123	                            optionValueCatalogMapping.put(optionValueId, catalog.getId());
1124	                        }
1125	                    }
1126	                }
1127	            }
1128	        }
1129	    }
1130	
