/**
 * 服务实现类
 *
 * @author author
 * @since 2024年11月14日
 */
@Service
@Slf4j
public class SolutionMaterialNumberServiceImpl extends ServiceImpl<SolutionMaterialNumberMapper, SolutionMaterialNumber> implements SolutionMaterialNumberService {
    @Autowired
    ConfigSolutionService configSolutionService;

    @Autowired
    SaleMaterialService saleMaterialService;
    @Autowired
    MaterialOptionRelationService materialOptionRelationService;

    @Autowired
    private ConfigCatalogValueService configCatalogValueService;

    @Autowired
    private ConfigCatalogGroupService configCatalogGroupService;

    @Autowired
    private ConfigGroupValueService configGroupValueService;

    @Autowired
    private ConfigCatalogService configCatalogService;

    @Autowired
    private PortalRelationService portalRelationService;

    @Autowired
    private MaterialPriceService materialPriceService;
    @Autowired
    private MaterialPriceCalcService materialPriceCalcService;
    @Autowired
    private SaleMaterialMapper saleMaterialMapper;

    @Autowired
    private ApplicationEventPublisher applicationEventPublisher;

    @Autowired
    private SolutionMaterialNumberMapper solutionMaterialNumberMapper;

    @Autowired
    private ConfigSolutionScopeService configSolutionScopeService;

    @Autowired
    private ConfigSolutionMapper configSolutionMapper;

    @Autowired
    private PriceManagementMapper priceManagementMapper;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void calcMaterialNumberPrice(List<String> solutionIds) {
        //查询所有有效的待确认的配置方案ID集合,不包含小型机
        LambdaQueryWrapper<ConfigSolution> wrapper = Wrappers.lambdaQuery(ConfigSolution.class)
                .eq(ConfigSolution::getFormStatus, FormStatusEnum.EFFECTIVE.getCode())
                .eq(ConfigSolution::getEnableStatus, EnableStatusEnum.ENABLE.getCode())
                .ne(ConfigSolution::getProductLineId, ProductLineType.COMPLEX_MACHINERY.getProductLineId());
        if (CollUtil.isNotEmpty(solutionIds)) {
            wrapper.in(ConfigSolution::getSolutionId, solutionIds);
        }
        List<ConfigSolution> solutionInfos = configSolutionService.list(wrapper);
        if (CollUtil.isEmpty(solutionInfos)) {
            log.info("solutionIds:{},没有找到配置方案！", solutionIds);
            return;
        }
        //循环配置方案ID，获取对应匹配的物料号
        TimeInterval timer = new TimeInterval();
        timer.start();
        List<SolutionMaterialNumber> solutionMaterialNumbers = new ArrayList<>();
        for (ConfigSolution solutionInfo : solutionInfos) {
            //获取配置方案匹配到得的物料号集合
            List<String> materialNumbers = getMatchedMaterialNumber(solutionInfo, null);
            if (CollUtil.isEmpty(materialNumbers)) {
                continue;
            }
            log.info("配置方案：{} 匹配的物料号集合：{}", solutionInfo.getSolutionId(), materialNumbers);
            buildSolutionMaterialNumberList(solutionInfo, solutionMaterialNumbers, materialNumbers);
        }
        long matchCost = timer.interval(); // 获取第一段耗时
        log.info("配置方案匹配物料号耗时：{}毫秒", matchCost);
        if (CollUtil.isEmpty(solutionMaterialNumbers)) {
            return;
        }
        log.info("需计算物料号价格的条数{}", solutionMaterialNumbers.size());
        //根据方案匹配的物料号计算价格
        timer.restart();
        List<MaterialPrice> materialPrices = calcMaterialPrice(solutionMaterialNumbers);
        long calcPriceCost = timer.interval();
        log.info("计算物料号价格耗时：{}毫秒", calcPriceCost);
        //批量保存配置方案和物料号价格数据
        if (CollUtil.isNotEmpty(materialPrices)) {
            //传指定配置方案来匹配并计算价格时， 不清空表数据
            if (CollUtil.isEmpty(solutionIds)) {
                materialPriceService.remove(Wrappers.lambdaQuery(MaterialPrice.class));
                materialPriceCalcService.remove(Wrappers.lambdaQuery(MaterialPriceCalc.class));
            }
            for (MaterialPrice materialPrice : materialPrices) {
                List<MaterialPriceCalc> calcList = materialPrice.getCalcList();
                materialPriceService.save(materialPrice);
                if (CollUtil.isNotEmpty(calcList)) {
                    calcList.forEach(item -> item.setMaterialPriceId(materialPrice.getId()));
                    materialPriceCalcService.saveBatch(calcList);
                }
            }
            if (CollUtil.isNotEmpty(solutionIds)) {
                //发布推送价格数据到MQ的事件
                applicationEventPublisher.publishEvent(new SendMaterialPriceEvent(materialPrices, UserContext.getUser()));
            }
        }

        //批量保存配置方案和物料号匹配数据
        /*if(CollUtil.isNotEmpty(solutionMaterialNumbers)) {
            //传指定配置方案来匹配并计算价格时， 不清空表数据
            if(CollUtil.isEmpty(solutionIds)) {
                remove(Wrappers.lambdaQuery(SolutionMaterialNumber.class));
            }
            saveBatch(solutionMaterialNumbers);
        }*/
    }

    /**
     * 物料价格计算
     *
     * @param solutionMaterialNumbers
     * @return
     */
    private List<MaterialPrice> calcMaterialPrice(List<SolutionMaterialNumber> solutionMaterialNumbers) {
        List<MaterialPrice> materialPrices = solutionMaterialNumbers.parallelStream()
                .flatMap(solutionMaterialNumber -> {
                    TimeInterval timer = new TimeInterval();
                    timer.restart();
                    List<MaterialPrice> subMaterialPrices = portalRelationService.calcSolutionMaterialPrice(solutionMaterialNumber);
                    log.info("配置方案：{},物料号：{},物料价格：{}",solutionMaterialNumber.getSolutionId(),solutionMaterialNumber.getMaterialNumber(), JSONUtil.toJsonStr(subMaterialPrices));
                    log.info("配置方案：{} 匹配物料号：{} 耗时：{}毫秒",solutionMaterialNumber.getSolutionId(),solutionMaterialNumber.getMaterialNumber(),timer.interval());
                    return CollUtil.isEmpty(subMaterialPrices)? Stream.empty():subMaterialPrices.stream();
                })
                .collect(Collectors.toList());

        return materialPrices;
    }


    /**
     * 构建配置方案和物料号匹配数据
     *
     * @param solutionInfo
     * @param solutionMaterialNumbers
     * @param materialNumbers
     */
    private static void buildSolutionMaterialNumberList(ConfigSolution solutionInfo, List<SolutionMaterialNumber> solutionMaterialNumbers, List<String> materialNumbers) {
        //封装创建数据
        solutionMaterialNumbers.addAll(materialNumbers.stream().map(materialNumber -> {
            SolutionMaterialNumber solutionMaterialNumber = new SolutionMaterialNumber();
            solutionMaterialNumber.setSolutionId(solutionInfo.getSolutionId());
            solutionMaterialNumber.setMaterialNumber(materialNumber);
            solutionMaterialNumber.setProductLineId(solutionInfo.getProductLineId());
            solutionMaterialNumber.setModelId(solutionInfo.getModelId());
            solutionMaterialNumber.setFormStatus(solutionInfo.getFormStatus());
            return solutionMaterialNumber;
        }).collect(Collectors.toList()));
    }

    /**
     * 根据配置方案获取配置方案匹配的物料号集合
     *
     * @param solutionInfo
     * @param materialNumbers
     * @return
     */
    @Override
    public List<String> getMatchedMaterialNumber(ConfigSolution solutionInfo, Collection<String> materialNumbers) {
        //获取配置方案相关数据
        SolutionRelationDataVo solutionRelationData = getSolutionRelationData(solutionInfo);
        if (solutionRelationData == null) {
            log.info("配置方案：{} 相关数据异常", solutionInfo.getSolutionId());
            return null;
        }
        //获取配置方案同机型的所有可售物料号
        List<SaleMaterial> saleMaterials = null;
        if (CollUtil.isNotEmpty(materialNumbers)) {
            saleMaterials = saleMaterialService.list(Wrappers.lambdaQuery(SaleMaterial.class).in(SaleMaterial::getMaterialNumber, materialNumbers).eq(SaleMaterial::getState, "1"));
        } else {
            saleMaterials = saleMaterialService.list(Wrappers.lambdaQuery(SaleMaterial.class).eq(SaleMaterial::getModelId, solutionInfo.getModelId()).eq(SaleMaterial::getState, "1"));
        }
        if (CollUtil.isEmpty(saleMaterials)) {
            log.info("配置方案：{} 同机型下无可售物料号", solutionInfo.getSolutionId());
            return null;
        }
        //获取物料号与配置项ID集合映射
        Map<String, Set<String>> materialOptionMap = getMaterialOptionMap(saleMaterials);
        //匹配结果
        List<String> matchedMaterialNumbers = new ArrayList<>();
        for (Map.Entry<String, Set<String>> materialOptionEntry : materialOptionMap.entrySet()) {
            Set<String> materialOptionValueIds = materialOptionEntry.getValue();
            //校验配置方案是否能匹配物料号
            if (checkSolutionMatchMaterial(solutionRelationData, materialOptionValueIds, materialOptionEntry.getKey())) {
                matchedMaterialNumbers.add(materialOptionEntry.getKey());
            }
        }
        return matchedMaterialNumbers;
    }

    /**
     * 校验配置方案是否能匹配物料号
     *
     * @param solutionRelationData
     * @param materialOptionValueIds
     * @param materialNumber
     * @return
     */
    private boolean checkSolutionMatchMaterial(SolutionRelationDataVo solutionRelationData, Set<String> materialOptionValueIds, String materialNumber) {
        //待选择的配置项（当没有值时，证明在此配置方案都可选择出此物料号下的所有配置项）
        Set<String> pendingSelectionMaterialOptions = new HashSet<>(materialOptionValueIds);
        log.info("配置方案：{},物料号：{}, 待选择的配置项：{},开始匹配", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
        //基本配置校验物料号是否满足
        if (!checkStatic(solutionRelationData, pendingSelectionMaterialOptions)) {
            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},基本配置校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
            return false;
        }
        //检查营销不可见的配置项是否满足
        if (CollUtil.isNotEmpty(solutionRelationData.getNoSaleNeedOptionValueIds()) && !pendingSelectionMaterialOptions.containsAll(solutionRelationData.getNoSaleNeedOptionValueIds())) {
            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},营销不可见的配置项校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
            return false;
        }
        if (CollUtil.isNotEmpty(solutionRelationData.getNoSaleNeedOptionValueIds()) && pendingSelectionMaterialOptions.containsAll(solutionRelationData.getNoSaleNeedOptionValueIds())) {
            solutionRelationData.getNoSaleNeedOptionValueIds().forEach(pendingSelectionMaterialOptions::remove);
        }
        //必选配置校验物料号是否满足
        if (!checkMust(solutionRelationData, pendingSelectionMaterialOptions)) {
            log.info("配置方案：{},物料号：{}, 待选择的配置项：{},必选配置校验不通过", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
            return false;
        }
        //可选配置校验物料号是否满足
        checkOptional(solutionRelationData, pendingSelectionMaterialOptions);
        //如果待选择的配置项不为空，则返回false
        log.info("配置方案id:{},物料号：{},待选择的配置项：{}", solutionRelationData.getSolutionId(), materialNumber, pendingSelectionMaterialOptions);
        return !CollUtil.isNotEmpty(pendingSelectionMaterialOptions);
    }

    /**
     * 可选配置校验物料号是否满足
     *
     * @param solutionRelationData
     * @param pendingSelectionMaterialOptions
     * @return
     */
    private void checkOptional(SolutionRelationDataVo solutionRelationData, Set<String> pendingSelectionMaterialOptions) {
        List<ConfigCatalog> optionalCatalogList = solutionRelationData.getOptionalCatalogList();
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
        //配置组合和其配置项的映射
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
        //如果可选项为空 且 待选择的配置项不为空，则返回false不匹配
        if (CollUtil.isEmpty(optionalCatalogList) && CollUtil.isNotEmpty(pendingSelectionMaterialOptions)) {
            return;
        }
        for (ConfigCatalog configCatalog : optionalCatalogList) {
            //分类下关联的配置项数据
            List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(configCatalog.getId());
            //分类下关联的配置组合数据
            List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(configCatalog.getId());
            //如果本分类没有配置项和配置组合数据，跳过本配置分类的校验（多级配置分类情况）
            if (CollUtil.isEmpty(configCatalogGroups) && CollUtil.isEmpty(configCatalogValues)) {
                continue;
            }
            if (SelectTypeEnum.SINGLE.getCode().equals(configCatalog.getSelectType())) {
                //单选匹配逻辑
                optionalSingleMatch(pendingSelectionMaterialOptions, configCatalogGroups, groupValueMapping, configCatalogValues);
            } else {
                //多选匹配
                optionalMutiMatch(pendingSelectionMaterialOptions, configCatalogValues, configCatalogGroups, groupValueMapping);
            }
        }
    }

    /**
     * 可选配置多选匹配逻辑
     *
     * @param pendingSelectionMaterialOptions
     * @param configCatalogValues
     * @param configCatalogGroups
     * @param groupValueMapping
     */
    private static void optionalMutiMatch(Set<String> pendingSelectionMaterialOptions, List<ConfigCatalogValue> configCatalogValues, List<ConfigCatalogGroup> configCatalogGroups, Map<String, Set<String>> groupValueMapping) {
        //配置组合匹配（已在数据来源处按配置项数量降序排序）
        if (CollUtil.isNotEmpty(configCatalogGroups)) {
            for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                if (CollUtil.isNotEmpty(optionValueIds) && pendingSelectionMaterialOptions.containsAll(optionValueIds)) {
                    pendingSelectionMaterialOptions.removeAll(optionValueIds);
                }
            }
        }
        //配置项匹配
        if (CollUtil.isNotEmpty(configCatalogValues)) {
            for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup()) && pendingSelectionMaterialOptions.contains(configCatalogValue.getOptionValueId())) {
                    pendingSelectionMaterialOptions.remove(configCatalogValue.getOptionValueId());
                }
            }
        }

    }

    /**
     * 可选配置的单选匹配逻辑
     *
     * @param pendingSelectionMaterialOptions
     * @param configCatalogGroups
     * @param groupValueMapping
     * @param configCatalogValues
     */
    private static void optionalSingleMatch(Set<String> pendingSelectionMaterialOptions, List<ConfigCatalogGroup> configCatalogGroups, Map<String, Set<String>> groupValueMapping, List<ConfigCatalogValue> configCatalogValues) {
        boolean groupMatchFlag = false;
        //配置组合匹配（已在数据来源处按配置项数量降序排序）
        if (CollUtil.isNotEmpty(configCatalogGroups)) {
            for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                if (CollUtil.isNotEmpty(optionValueIds) && pendingSelectionMaterialOptions.containsAll(optionValueIds)) {
                    pendingSelectionMaterialOptions.removeAll(optionValueIds);
                    groupMatchFlag = true;
                    break;
                }
            }
        }
        //组合匹配通过，跳过非组合的配置项匹配
        if (groupMatchFlag) {
            return;
        }
        //配置项匹配
        if (CollUtil.isNotEmpty(configCatalogValues)) {
            for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup()) && pendingSelectionMaterialOptions.contains(configCatalogValue.getOptionValueId())) {
                    pendingSelectionMaterialOptions.remove(configCatalogValue.getOptionValueId());
                    break;
                }
            }
        }
    }

    /**
     * 必选配置校验物料号是否满足
     *
     * @param solutionRelationData
     * @param pendingSelectionMaterialOptions
     * @return
     */
    private boolean checkMust(SolutionRelationDataVo solutionRelationData, Set<String> pendingSelectionMaterialOptions) {
        List<ConfigCatalog> mustCatalogList = solutionRelationData.getMustCatalogList();
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
        for (ConfigCatalog configCatalog : mustCatalogList) {
            boolean optionMatchFlag = false;
            boolean groupMatchFlag = false;
            //分类下关联的配置项数据
            List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(configCatalog.getId());
            //分类下关联的配置组合数据
            List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(configCatalog.getId());
            //如果本分类没有配置项和配置组合数据，跳过本配置分类的校验（多级配置分类情况）
            if (CollUtil.isEmpty(configCatalogGroups) && CollUtil.isEmpty(configCatalogValues)) {
                continue;
            }
            //配置组合匹配（已在数据来源处按配置项数量降序排序）
            if (CollUtil.isNotEmpty(configCatalogGroups)) {
                for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                    Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                    if (CollUtil.isNotEmpty(optionValueIds) && pendingSelectionMaterialOptions.containsAll(optionValueIds)) {
                        pendingSelectionMaterialOptions.removeAll(optionValueIds);
                        groupMatchFlag = true;
                        break;
                    }
                }
            }
            //组合匹配通过，跳过非组合的配置项匹配
            if (groupMatchFlag) {
                continue;
            }
            //配置项匹配
            if (CollUtil.isNotEmpty(configCatalogValues)) {
                for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                    if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup()) && pendingSelectionMaterialOptions.contains(configCatalogValue.getOptionValueId())) {
                        pendingSelectionMaterialOptions.remove(configCatalogValue.getOptionValueId());
                        optionMatchFlag = true;
                        break;
                    }
                }
            }
            if (!optionMatchFlag) {
                return false;
            }
        }

        return true;
    }

    private boolean checkStatic(SolutionRelationDataVo solutionRelationData, Set<String> pendingSelectionMaterialOptions) {
        List<ConfigCatalog> staticCatalogList = solutionRelationData.getStaticCatalogList();
        //取基本配置分类的所有分类ID
        Set<Long> staticCatalogIds = staticCatalogList.stream().map(ConfigCatalog::getId).collect(Collectors.toSet());
        //获取基本配置分类下所有配置项值
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
        Set<String> staticOptionValues = new HashSet<>();
        for (Long staticCatalogId : staticCatalogIds) {
            List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(staticCatalogId);
            List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(staticCatalogId);
            if (CollUtil.isEmpty(configCatalogValues) && CollUtil.isEmpty(configCatalogGroups)) {
                continue;
            }
            //根据分类和配置项映射，获取所有配置项值
            if (CollUtil.isNotEmpty(configCatalogValues)) {
                for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                    if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup())) {
                        staticOptionValues.add(configCatalogValue.getOptionValueId());
                    }
                }
            }
            //根据分类和配置组合映射，获取所有配置组合，获取所有配置组合对应的配置项值
            if (CollUtil.isNotEmpty(configCatalogGroups)) {
                for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                    Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                    staticOptionValues.addAll(optionValueIds);
                }
            }
        }
        //判断待选择的配置项是否包含所有基本配置项
        if (pendingSelectionMaterialOptions.containsAll(staticOptionValues)) {
            pendingSelectionMaterialOptions.removeAll(staticOptionValues);
            return true;
        }
        return false;
    }

    /**
     * 获取物料号与配置项ID集合映射
     *
     * @param saleMaterials
     * @return
     */
    private Map<String, Set<String>> getMaterialOptionMap(List<SaleMaterial> saleMaterials) {
        // 获取物料号集合
        Set<String> materialNumbers = saleMaterials.stream().map(SaleMaterial::getMaterialNumber).collect(Collectors.toSet());
        //获取物料号的所有配置项
        List<MaterialOptionRelation> allMaterialOptions = materialOptionRelationService.list(Wrappers.lambdaQuery(MaterialOptionRelation.class).in(MaterialOptionRelation::getMaterialNumber, materialNumbers));

        return allMaterialOptions.stream().collect(Collectors.groupingBy(
                MaterialOptionRelation::getMaterialNumber,
                Collectors.mapping(
                        MaterialOptionRelation::getOptionValueId,
                        Collectors.toSet()
                )
        ));
    }

    /**
     * 获取配置方案相关数据
     *
     * @param solutionInfo
     * @return
     */
    private SolutionRelationDataVo getSolutionRelationData(ConfigSolution solutionInfo) {
        SolutionRelationDataVo solutionRelationDataVo = new SolutionRelationDataVo();
        //获取配置方案下所有的配置分类和配置组合的集合
        List<ConfigCatalog> configCatalogList = configCatalogService.list(Wrappers.lambdaQuery(ConfigCatalog.class).eq(ConfigCatalog::getSolutionId, solutionInfo.getSolutionId()));
        if (CollUtil.isEmpty(configCatalogList)) {
            log.info("配置方案{}配置分类为空", solutionInfo.getSolutionId());
            return null;
        }
        //获取配置方案基本型所有分类
        List<ConfigCatalog> staticCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.STATIC.getCode())).collect(Collectors.toList());
        //获取配置方案必选所有分类
        List<ConfigCatalog> mustCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.MUST.getCode())).collect(Collectors.toList());
        //获取配置方案可选所有分类
        List<ConfigCatalog> optionalCatalogList = configCatalogList.stream().filter(item -> item.getConfigType().equals(ConfigType.OPTIONAL.getCode())).collect(Collectors.toList());
        List<Long> allCatalogIds = configCatalogList.stream().map(ConfigCatalog::getId).collect(Collectors.toList());
        //获取所有配置分类下和配置项集合的映射
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = configCatalogValueService.list(Wrappers.lambdaQuery(ConfigCatalogValue.class).in(ConfigCatalogValue::getCatalogId, allCatalogIds)).stream().collect(Collectors.groupingBy(
                ConfigCatalogValue::getCatalogId
        ));
        //获取所有配置分类下和配置组合集合的映射
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = configCatalogGroupService.list(Wrappers.lambdaQuery(ConfigCatalogGroup.class).in(ConfigCatalogGroup::getCatalogId, allCatalogIds)).stream().collect(Collectors.groupingBy(
                ConfigCatalogGroup::getCatalogId
        ));
        //配置组合ID集合
        Set<String> allGroupIds = new HashSet<>();
        //配置组合ID和配置项的映射
        Map<String, Set<String>> groupValueMapping = new HashMap<>();
        if (!catalogGroupMapping.isEmpty()) {
            allGroupIds = catalogGroupMapping.values().stream().flatMap(List::stream).map(ConfigCatalogGroup::getGroupId).collect(Collectors.toSet());
            //设置配置组合ID和配置项的映射
            setGroupValueMapping(allGroupIds, groupValueMapping);
        }
        //查询营销不可见的配置项ID集合
        List<String> noSaleNeedOptionValueIds = new ArrayList<>();
        List<SaleMaterialOptionValueVO> saleMaterialOptionValueVOList = saleMaterialMapper.queryMaterialOptionValuesNoNeed(solutionInfo.getMaterialNumber());
        if (CollUtil.isNotEmpty(saleMaterialOptionValueVOList)) {
            List<String> optionValueIdList = saleMaterialOptionValueVOList.stream().map(SaleMaterialOptionValueVO::getOptionValueId).collect(Collectors.toList());
            if (CollUtil.isNotEmpty(optionValueIdList)) {
                noSaleNeedOptionValueIds.addAll(optionValueIdList);
            }
        }
        //组装参数返回
        solutionRelationDataVo.setConfigCatalogList(configCatalogList);
        solutionRelationDataVo.setAllCatalogIds(allCatalogIds);
        solutionRelationDataVo.setStaticCatalogList(staticCatalogList);
        solutionRelationDataVo.setSolutionId(solutionInfo.getSolutionId());
        solutionRelationDataVo.setMustCatalogList(mustCatalogList);
        solutionRelationDataVo.setOptionalCatalogList(optionalCatalogList);
        solutionRelationDataVo.setCatalogValueMapping(catalogValueMapping);
        // 对catalogGroupMapping中每个配置分类下的配置组合列表按配置项数量降序排序
        Map<Long, List<ConfigCatalogGroup>> sortedCatalogGroupMapping = sortCatalogGroupMappingByGroupSize(catalogGroupMapping, groupValueMapping);
        solutionRelationDataVo.setCatalogGroupMapping(sortedCatalogGroupMapping);
        solutionRelationDataVo.setGroupValueMapping(groupValueMapping);
        solutionRelationDataVo.setAllGroupIds(allGroupIds);
        solutionRelationDataVo.setNoSaleNeedOptionValueIds(noSaleNeedOptionValueIds);
        return solutionRelationDataVo;
    }

    /**
     * 对配置分类下的配置组合列表按配置组合包含的配置项数量降序排序
     * 配置项多的配置组合排在前面，这样可以优先匹配大的配置组合，最大化排除pendingSelectionMaterialOptions
     *
     * @param catalogGroupMapping 配置分类和配置组合的映射
     * @param groupValueMapping   配置组合和配置项的映射
     * @return 排序后的映射
     */
    private Map<Long, List<ConfigCatalogGroup>> sortCatalogGroupMappingByGroupSize(
            Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping,
            Map<String, Set<String>> groupValueMapping) {
        Map<Long, List<ConfigCatalogGroup>> sortedMapping = new HashMap<>();
        for (Map.Entry<Long, List<ConfigCatalogGroup>> entry : catalogGroupMapping.entrySet()) {
            Long catalogId = entry.getKey();
            List<ConfigCatalogGroup> groups = entry.getValue();
            if (CollUtil.isNotEmpty(groups)) {
                // 按配置组合拥有的配置项数量降序排序
                List<ConfigCatalogGroup> sortedGroups = groups.stream()
                        .sorted((g1, g2) -> {
                            Set<String> ids1 = groupValueMapping.get(g1.getGroupId());
                            Set<String> ids2 = groupValueMapping.get(g2.getGroupId());
                            int size1 = ids1 != null ? ids1.size() : 0;
                            int size2 = ids2 != null ? ids2.size() : 0;
                            return Integer.compare(size2, size1); // 降序排序
                        })
                        .collect(Collectors.toList());
                sortedMapping.put(catalogId, sortedGroups);
            } else {
                sortedMapping.put(catalogId, groups);
            }
        }
        return sortedMapping;
    }

    /**
     * 设置配置组合ID和配置项的映射
     *
     * @param allGroupIds
     * @param groupValueMapping
     */
    private void setGroupValueMapping(Set<String> allGroupIds, Map<String, Set<String>> groupValueMapping) {
        //获取配置组合ID和配置项ID集合的映射
        if (CollUtil.isNotEmpty(allGroupIds)) {
            List<ConfigGroupValue> configGroupValueList = configGroupValueService.list(Wrappers.lambdaQuery(ConfigGroupValue.class).in(ConfigGroupValue::getGroupId, allGroupIds));
            for (ConfigGroupValue configGroupValue : configGroupValueList) {
                Set<String> optionValueIdSet = groupValueMapping.get(configGroupValue.getGroupId());
                if (optionValueIdSet == null) {
                    optionValueIdSet = new HashSet<>();
                    optionValueIdSet.add(configGroupValue.getOptionValueId());
                }
                optionValueIdSet.add(configGroupValue.getOptionValueId());
                groupValueMapping.put(configGroupValue.getGroupId(), optionValueIdSet);
            }
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void matchAndSave() {
        //查询所有的配置方案数据,不包含小型机
        LambdaQueryWrapper<ConfigSolution> wrapper = Wrappers.lambdaQuery(ConfigSolution.class)
                .ne(ConfigSolution::getProductLineId, ProductLineType.COMPLEX_MACHINERY.getProductLineId());
        List<ConfigSolution> solutionInfos = configSolutionService.list(wrapper);
        if (CollUtil.isEmpty(solutionInfos)) {
            log.info("没有配置方案数据！");
            return;
        }
        List<SolutionMaterialNumber> solutionMaterialNumbers = new ArrayList<>();
        for (ConfigSolution solutionInfo : solutionInfos) {
            //获取配置方案匹配到得的物料号集合
            List<String> materialNumbers = getMatchedMaterialNumber(solutionInfo, null);
            if (CollUtil.isEmpty(materialNumbers)) {
                continue;
            }
            log.info("配置方案：{} 匹配的物料号集合：{}", solutionInfo.getSolutionId(), materialNumbers);
            buildSolutionMaterialNumberList(solutionInfo, solutionMaterialNumbers, materialNumbers);
        }
        //批量保存配置方案和物料号匹配数据
        if (CollUtil.isNotEmpty(solutionMaterialNumbers)) {
            //清除原有记录
            remove(Wrappers.lambdaQuery(SolutionMaterialNumber.class));
            //保存新的匹配结果
            saveBatch(solutionMaterialNumbers);
        }
    }

    @Override
    public IPage<MaterialNumberMatchVO> getDataListByPage(MaterialNumberMatchQueryDTO queryDto) {
        log.info("ConfigSolutionServiceImpl.getDataListByPage queryDto:{}", queryDto);
        // 构建分页对象并执行SQL查询
        Page<MaterialNumberMatchVO> page = new Page<>(queryDto.getPage(), queryDto.getRows());

        return solutionMaterialNumberMapper.getDataListByPage(page, queryDto.getDto());
    }

    @Override
    public List<MaterialNumberMatchExcelVO> download(MaterialNumberMatchDTO queryDto) {
        //查询数据
        List<MaterialNumberMatchVO> MaterialNumberMatchVOS = solutionMaterialNumberMapper.queryMatchList(queryDto);
        return MaterialNumberMatchExcelVO.transferVo(MaterialNumberMatchVOS);
    }

    /**
     * 根据物料号反向获取匹配的配置方案ID列表
     *
     * @param materialNumber 物料号
     * @param country        国家（可选，用于过滤配置方案适用范围）
     * @return 匹配的配置方案ID列表
     */
    @Override
    public List<String> getMatchedSolutionIds(String materialNumber, String country) {
        // 查询物料号基本信息
        SaleMaterial saleMaterial = saleMaterialService.getSaleMaterialByNumber(materialNumber);
        if (saleMaterial == null) {
            log.info("物料号：{} 不存在", materialNumber);
            return null;
        }
        // 查询该机型下所有生效的配置方案
        List<ConfigSolution> solutionList = configSolutionService.list(
                Wrappers.lambdaQuery(ConfigSolution.class)
                        .eq(ConfigSolution::getModelId, saleMaterial.getModelId())
                        .eq(ConfigSolution::getFormStatus, FormStatusEnum.EFFECTIVE.getCode())
                        .ne(ConfigSolution::getProductLineId, ProductLineType.COMPLEX_MACHINERY.getProductLineId())
        );
        if (CollUtil.isEmpty(solutionList)) {
            log.info("物料号：{} 同机型下没有生效的配置方案", materialNumber);
            return null;
        }
        // 如果指定了国家，则根据配置方案的适用范围过滤
        if (StringUtils.isNotBlank(country)) {
            // 查询所有方案的国家适用范围
            List<String> solutionIds = solutionList.stream().map(ConfigSolution::getSolutionId).collect(Collectors.toList());
            List<ConfigSolutionScope> scopeList = configSolutionScopeService.list(
                    Wrappers.lambdaQuery(ConfigSolutionScope.class)
                            .in(ConfigSolutionScope::getSolutionId, solutionIds)
                            .eq(ConfigSolutionScope::getCountry, country)
            );
            // 获取符合国家范围的方案ID集合
            Set<String> validSolutionIds = scopeList.stream().map(ConfigSolutionScope::getSolutionId).collect(Collectors.toSet());
            // 过滤方案列表
            solutionList = solutionList.stream()
                    .filter(solution -> validSolutionIds.contains(solution.getSolutionId()))
                    .collect(Collectors.toList());
            if (CollUtil.isEmpty(solutionList)) {
                log.info("物料号：{} 同机型下没有适用于国家 {} 的配置方案", materialNumber, country);
                return null;
            }
        }
        // 获取物料号关联的配置项ID集合
        Set<String> materialOptionValueIds = getMaterialOptionValueIds(materialNumber);
        if (CollUtil.isEmpty(materialOptionValueIds)) {
            log.info("物料号：{} 没有关联的配置项", materialNumber);
            return null;
        }
        // 遍历配置方案，判断物料号是否匹配
        List<String> matchedSolutionIds = new ArrayList<>();
        for (ConfigSolution solution : solutionList) {
            // 获取配置方案相关数据
            SolutionRelationDataVo solutionRelationData = getSolutionRelationData(solution);
            if (solutionRelationData == null) {
                continue;
            }
            // 校验是否匹配
            if (checkSolutionMatchMaterial(solutionRelationData, new HashSet<>(materialOptionValueIds), materialNumber)) {
                matchedSolutionIds.add(solution.getSolutionId());
            }
        }
        return matchedSolutionIds;
    }

    /**
     * 根据物料号和配置方案获取匹配关系数据（用于价格校验）
     *
     * @param materialNumber 物料号
     * @param solutionId     配置方案ID
     * @return 物料号在该配置方案中的匹配关系数据
     */
    @Override
    public MaterialNumberMatchRelationVO getMaterialNumberMatchRelation(String materialNumber, String solutionId) {
        // 查询物料号基本信息
        SaleMaterial saleMaterial = saleMaterialService.getSaleMaterialByNumber(materialNumber);
        if (saleMaterial == null) {
            log.info("物料号：{} 不存在", materialNumber);
            return null;
        }
        // 查询配置方案
        ConfigSolution solution = configSolutionService.getOne(
                Wrappers.lambdaQuery(ConfigSolution.class).eq(ConfigSolution::getSolutionId, solutionId));
        if (solution == null) {
            log.info("配置方案：{} 不存在", solutionId);
            return null;
        }
        // 获取配置方案相关数据
        SolutionRelationDataVo solutionRelationData = getSolutionRelationData(solution);
        if (solutionRelationData == null) {
            return null;
        }
        // 获取物料号关联的配置项ID集合
        Set<String> materialOptionValueIds = getMaterialOptionValueIds(materialNumber);
        if (CollUtil.isEmpty(materialOptionValueIds)) {
            return null;
        }
        // 构建匹配关系数据
        MaterialNumberMatchRelationVO relationVO = buildMatchRelationVO(solutionRelationData,
                new HashSet<>(materialOptionValueIds), solution);
        return relationVO;
    }

    /**
     * 获取物料号关联的配置项ID集合
     *
     * @param materialNumber 物料号
     * @return 配置项ID集合
     */
    private Set<String> getMaterialOptionValueIds(String materialNumber) {
        List<MaterialOptionRelation> materialOptionRelations = materialOptionRelationService.list(
                Wrappers.lambdaQuery(MaterialOptionRelation.class)
                        .eq(MaterialOptionRelation::getMaterialNumber, materialNumber));
        if (CollUtil.isEmpty(materialOptionRelations)) {
            return null;
        }
        return materialOptionRelations.stream()
                .map(MaterialOptionRelation::getOptionValueId)
                .collect(Collectors.toSet());
    }

    /**
     * 构建物料号匹配关系VO
     *
     * @param solutionRelationData   配置方案相关数据
     * @param materialOptionValueIds 物料号配置项ID集合
     * @param solution               配置方案
     * @return 匹配关系VO
     */
    private MaterialNumberMatchRelationVO buildMatchRelationVO(SolutionRelationDataVo solutionRelationData,
                                                               Set<String> materialOptionValueIds, ConfigSolution solution) {
        MaterialNumberMatchRelationVO relationVO = new MaterialNumberMatchRelationVO();
        relationVO.setSolutionId(solution.getSolutionId());
        relationVO.setMaterialNumber(solution.getMaterialNumber());
        relationVO.setModelId(solution.getModelId());

        // 获取基本配置项ID集合
        Set<String> staticOptionValueIds = getStaticOptionValueIds(solutionRelationData);
        relationVO.setStaticOptionValueIds(staticOptionValueIds);

        // 获取NC配置项ID集合和有NC项的分类ID集合（后续会过滤）
        Set<Long> catalogIdsWithNc = new HashSet<>();
        Map<Long, Set<String>> catalogNcOptionValueIds = new HashMap<>();
        Set<String> ncOptionValueIds = getNcOptionValueIdsAndCatalogIds(solutionRelationData,
                catalogIdsWithNc, catalogNcOptionValueIds);
        relationVO.setNcOptionValueIds(ncOptionValueIds);

        // 获取匹配的配置组合ID集合和groupId到catalogId的映射
        Map<String, Long> groupCatalogMapping = new HashMap<>();
        Set<String> matchedGroupIds = getMatchedGroupIdsWithCatalogMapping(solutionRelationData,
                materialOptionValueIds, groupCatalogMapping);
        relationVO.setGroupIds(matchedGroupIds);
        relationVO.setGroupCatalogMapping(groupCatalogMapping);

        // 获取匹配的配置项ID集合和optionValueId到catalogId的映射
        Map<String, Long> optionValueCatalogMapping = new HashMap<>();
        Set<String> matchedOptionValueIds = new HashSet<>();
        buildMatchedOptionValueIds(solutionRelationData, materialOptionValueIds, staticOptionValueIds,
                ncOptionValueIds, matchedGroupIds, matchedOptionValueIds, optionValueCatalogMapping);
        relationVO.setOptionValueIds(matchedOptionValueIds);
        relationVO.setOptionValueCatalogMapping(optionValueCatalogMapping);

        // 过滤catalogIdsWithNc：只保留有NC项但物料号不包含该分类下NC项的分类
        // 如果物料号包含该分类下的NC项，则该分类不需要减去NC项价格
        filterCatalogIdsWithNc(catalogIdsWithNc, catalogNcOptionValueIds, materialOptionValueIds,
                matchedGroupIds, matchedOptionValueIds, groupCatalogMapping, optionValueCatalogMapping);
        relationVO.setCatalogIdsWithNc(catalogIdsWithNc);

        return relationVO;
    }

    /**
     * 过滤catalogIdsWithNc：只保留需要减去NC项价格的分类
     * 规则：分类有NC项，物料号匹配了该分类下的非NC项，但物料号不包含该分类下的NC项
     *
     * @param catalogIdsWithNc          有NC项的分类ID集合（输入输出参数）
     * @param catalogNcOptionValueIds   每个分类的NC项ID集合
     * @param materialOptionValueIds    物料号原始配置项ID集合
     * @param matchedGroupIds           匹配的配置组合ID集合
     * @param matchedOptionValueIds     匹配的配置项ID集合
     * @param groupCatalogMapping       配置组合到分类的映射
     * @param optionValueCatalogMapping 配置项到分类的映射
     */
    private void filterCatalogIdsWithNc(Set<Long> catalogIdsWithNc, Map<Long, Set<String>> catalogNcOptionValueIds,
                                        Set<String> materialOptionValueIds, Set<String> matchedGroupIds, Set<String> matchedOptionValueIds,
                                        Map<String, Long> groupCatalogMapping, Map<String, Long> optionValueCatalogMapping) {
        // 收集物料号匹配的分类ID集合（匹配了非NC项的分类）
        Set<Long> matchedCatalogIds = new HashSet<>();
        if (CollUtil.isNotEmpty(matchedGroupIds)) {
            for (String groupId : matchedGroupIds) {
                Long catalogId = groupCatalogMapping.get(groupId);
                if (catalogId != null) {
                    matchedCatalogIds.add(catalogId);
                }
            }
        }
        if (CollUtil.isNotEmpty(matchedOptionValueIds)) {
            for (String optionValueId : matchedOptionValueIds) {
                Long catalogId = optionValueCatalogMapping.get(optionValueId);
                if (catalogId != null) {
                    matchedCatalogIds.add(catalogId);
                }
            }
        }

        // 过滤catalogIdsWithNc：只保留满足条件的分类
        Set<Long> filteredCatalogIdsWithNc = new HashSet<>();
        for (Long catalogId : catalogIdsWithNc) {
            // 条件1：物料号匹配了该分类下的非NC项（分类在matchedCatalogIds中）
            if (!matchedCatalogIds.contains(catalogId)) {
                continue;
            }
            // 条件2：物料号不包含该分类下的NC项
            Set<String> ncIds = catalogNcOptionValueIds.get(catalogId);
            if (CollUtil.isNotEmpty(ncIds)) {
                boolean materialContainsNc = false;
                for (String ncId : ncIds) {
                    if (materialOptionValueIds.contains(ncId)) {
                        materialContainsNc = true;
                        break;
                    }
                }
                // 如果物料号包含该分类下的NC项，则不需要减去NC项价格
                if (materialContainsNc) {
                    continue;
                }
            }
            // 满足条件：该分类需要减去NC项价格
            filteredCatalogIdsWithNc.add(catalogId);
        }
        catalogIdsWithNc.clear();
        catalogIdsWithNc.addAll(filteredCatalogIdsWithNc);
    }

    /**
     * 获取基本配置项ID集合
     *
     * @param solutionRelationData 配置方案相关数据
     * @return 基本配置项ID集合
     */
    private Set<String> getStaticOptionValueIds(SolutionRelationDataVo solutionRelationData) {
        Set<String> staticOptionValueIds = new HashSet<>();
        List<ConfigCatalog> staticCatalogList = solutionRelationData.getStaticCatalogList();
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();

        if (CollUtil.isNotEmpty(staticCatalogList)) {
            for (ConfigCatalog staticCatalog : staticCatalogList) {
                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(staticCatalog.getId());
                if (CollUtil.isNotEmpty(configCatalogValues)) {
                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                        if (!OptionValueGroupEnum.GROUP.getCode().equals(configCatalogValue.getOptionValueGroup())) {
                            staticOptionValueIds.add(configCatalogValue.getOptionValueId());
                        }
                    }
                }
                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(staticCatalog.getId());
                if (CollUtil.isNotEmpty(configCatalogGroups)) {
                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                        Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                        if (CollUtil.isNotEmpty(optionValueIds)) {
                            staticOptionValueIds.addAll(optionValueIds);
                        }
                    }
                }
            }
        }
        return staticOptionValueIds;
    }

    /**
     * 获取NC配置项ID集合和有NC项的分类ID集合
     *
     * @param solutionRelationData    配置方案相关数据
     * @param catalogIdsWithNc        有NC项的分类ID集合（输出参数，后续会过滤）
     * @param catalogNcOptionValueIds 每个分类的NC项ID集合（输出参数）
     * @return NC配置项ID集合
     */
    private Set<String> getNcOptionValueIdsAndCatalogIds(SolutionRelationDataVo solutionRelationData,
                                                         Set<Long> catalogIdsWithNc, Map<Long, Set<String>> catalogNcOptionValueIds) {
        Set<String> ncOptionValueIds = new HashSet<>();
        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();

        // 排除基本配置分类
        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
                .collect(Collectors.toList());

        if (CollUtil.isNotEmpty(otherCatalogList)) {
            for (ConfigCatalog catalog : otherCatalogList) {
                Set<String> catalogNcIds = new HashSet<>();
                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(catalog.getId());
                if (CollUtil.isNotEmpty(configCatalogValues)) {
                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                        if ("1".equals(configCatalogValue.getOptionValueNc())) {
                            ncOptionValueIds.add(configCatalogValue.getOptionValueId());
                            catalogNcIds.add(configCatalogValue.getOptionValueId());
                        }
                    }
                }
                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(catalog.getId());
                if (CollUtil.isNotEmpty(configCatalogGroups)) {
                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                        if ("1".equals(configCatalogGroup.getGroupNc())) {
                            Set<String> optionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                            if (CollUtil.isNotEmpty(optionValueIds)) {
                                ncOptionValueIds.addAll(optionValueIds);
                                catalogNcIds.addAll(optionValueIds);
                            }
                        }
                    }
                }
                // 记录有NC项的分类ID和该分类的NC项ID集合
                if (!catalogNcIds.isEmpty()) {
                    catalogIdsWithNc.add(catalog.getId());
                    catalogNcOptionValueIds.put(catalog.getId(), catalogNcIds);
                }
            }
        }
        return ncOptionValueIds;
    }

    /**
     * 获取匹配的配置组合ID集合和groupId到catalogId的映射
     *
     * @param solutionRelationData   配置方案相关数据
     * @param materialOptionValueIds 物料号配置项ID集合
     * @param groupCatalogMapping    groupId到catalogId的映射（输出参数）
     * @return 匹配的配置组合ID集合
     */
    private Set<String> getMatchedGroupIdsWithCatalogMapping(SolutionRelationDataVo solutionRelationData,
                                                             Set<String> materialOptionValueIds, Map<String, Long> groupCatalogMapping) {
        Set<String> matchedGroupIds = new HashSet<>();
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
        Map<Long, List<ConfigCatalogGroup>> catalogGroupMapping = solutionRelationData.getCatalogGroupMapping();

        // 排除基本配置分类
        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
                .collect(Collectors.toList());

        if (CollUtil.isNotEmpty(otherCatalogList)) {
            for (ConfigCatalog catalog : otherCatalogList) {
                // 判断是否需要匹配后跳出：必选配置 或 可选配置单选
                boolean shouldBreakOnMatch = ConfigType.MUST.getCode().equals(catalog.getConfigType())
                        || (ConfigType.OPTIONAL.getCode().equals(catalog.getConfigType())
                        && SelectTypeEnum.SINGLE.getCode().equals(catalog.getSelectType()));
                List<ConfigCatalogGroup> configCatalogGroups = catalogGroupMapping.get(catalog.getId());
                if (CollUtil.isNotEmpty(configCatalogGroups)) {
                    for (ConfigCatalogGroup configCatalogGroup : configCatalogGroups) {
                        // 排除NC配置组合
                        if ("1".equals(configCatalogGroup.getGroupNc())) {
                            continue;
                        }
                        Set<String> groupOptionValueIds = groupValueMapping.get(configCatalogGroup.getGroupId());
                        if (CollUtil.isNotEmpty(groupOptionValueIds)
                                && materialOptionValueIds.containsAll(groupOptionValueIds)) {
                            matchedGroupIds.add(configCatalogGroup.getGroupId());
                            // 记录groupId到catalogId的映射
                            groupCatalogMapping.put(configCatalogGroup.getGroupId(), catalog.getId());
                            // 必选配置或可选配置单选时，匹配到后结束该分类的匹配
                            if (shouldBreakOnMatch) {
                                break;
                            }
                        }
                    }
                }
            }
        }
        return matchedGroupIds;
    }

    /**
     * 构建匹配的配置项ID集合和optionValueId到catalogId的映射
     *
     * @param solutionRelationData      配置方案相关数据
     * @param materialOptionValueIds    物料号配置项ID集合
     * @param staticOptionValueIds      基本配置项ID集合
     * @param ncOptionValueIds          NC配置项ID集合
     * @param matchedGroupIds           匹配的配置组合ID集合
     * @param matchedOptionValueIds     匹配的配置项ID集合（输出参数）
     * @param optionValueCatalogMapping optionValueId到catalogId的映射（输出参数）
     */
    private void buildMatchedOptionValueIds(SolutionRelationDataVo solutionRelationData,
                                            Set<String> materialOptionValueIds, Set<String> staticOptionValueIds, Set<String> ncOptionValueIds,
                                            Set<String> matchedGroupIds, Set<String> matchedOptionValueIds,
                                            Map<String, Long> optionValueCatalogMapping) {
        Map<String, Set<String>> groupValueMapping = solutionRelationData.getGroupValueMapping();
        List<ConfigCatalog> configCatalogList = solutionRelationData.getConfigCatalogList();
        Map<Long, List<ConfigCatalogValue>> catalogValueMapping = solutionRelationData.getCatalogValueMapping();

        // 排除基本配置分类
        List<ConfigCatalog> otherCatalogList = configCatalogList.stream()
                .filter(catalog -> !ConfigType.STATIC.getCode().equals(catalog.getConfigType()))
                .collect(Collectors.toList());

        if (CollUtil.isNotEmpty(otherCatalogList)) {
            for (ConfigCatalog catalog : otherCatalogList) {
                List<ConfigCatalogValue> configCatalogValues = catalogValueMapping.get(catalog.getId());
                if (CollUtil.isNotEmpty(configCatalogValues)) {
                    for (ConfigCatalogValue configCatalogValue : configCatalogValues) {
                        String optionValueId = configCatalogValue.getOptionValueId();
                        // 排除NC配置项、基本配置项
                        if ("1".equals(configCatalogValue.getOptionValueNc())) {
                            continue;
                        }
                        if (staticOptionValueIds.contains(optionValueId)) {
                            continue;
                        }
                        if (ncOptionValueIds.contains(optionValueId)) {
                            continue;
                        }
                        // 排除已包含在匹配的配置组合中的配置项
                        boolean isInMatchedGroup = false;
                        if (CollUtil.isNotEmpty(matchedGroupIds)) {
                            for (String groupId : matchedGroupIds) {
                                Set<String> groupOptionValueIds = groupValueMapping.get(groupId);
                                if (CollUtil.isNotEmpty(groupOptionValueIds) && groupOptionValueIds.contains(optionValueId)) {
                                    isInMatchedGroup = true;
                                    break;
                                }
                            }
                        }
                        if (isInMatchedGroup) {
                            continue;
                        }
                        // 物料号包含该配置项
                        if (materialOptionValueIds.contains(optionValueId)) {
                            matchedOptionValueIds.add(optionValueId);
                            // 记录optionValueId到catalogId的映射
                            optionValueCatalogMapping.put(optionValueId, catalog.getId());
                        }
                    }
                }
            }
        }
    }

    /**
     * 获取配置方案相关数据（对外暴露）
     *
     * @param solutionInfo 配置方案
     * @return 配置方案相关数据
     */
    public SolutionRelationDataVo getSolutionRelationDataPublic(ConfigSolution solutionInfo) {
        return getSolutionRelationData(solutionInfo);
    }
}

