package com.ey.cpqcore.event;

import com.ey.cpqcore.entity.MaterialPrice;
import com.ey.cpqcore.vo.UserAccountShowVO;
import lombok.Data;
import lombok.ToString;
import org.springframework.context.ApplicationEvent;

import java.util.List;

/**
 * 发送物料价格数据到MQ事件
 */
@ToString
public class SendMaterialPriceEvent extends ApplicationEvent {
    /**
     * 物料价格数据集合
     */
    private List<MaterialPrice> materialPrices;

    private UserAccountShowVO baseUser;


    public SendMaterialPriceEvent() {
        super("");
    }

    public SendMaterialPriceEvent(List<MaterialPrice> materialPrices, UserAccountShowVO baseUser) {
        super("");
        this.materialPrices = materialPrices;
        this.baseUser = baseUser;
    }

    public List<MaterialPrice> getMaterialPrices() {
        return materialPrices;
    }

    public void setMaterialPrices(List<MaterialPrice> materialPrices) {
        this.materialPrices = materialPrices;
    }

    public UserAccountShowVO getBaseUser() {
        return baseUser;
    }
}

