package com.ey.cpqserver.message.producer;

import cn.hutool.core.collection.CollUtil;
import cn.hutool.core.date.DateUtil;
import com.alibaba.fastjson.JSONObject;
import com.ey.cpqcore.context.UserContext;
import com.ey.cpqcore.dto.message.ProductMarketDesMsgDTO;
import com.ey.cpqcore.dto.message.SendMaterialPriceDTO;
import com.ey.cpqcore.entity.MaterialPrice;
import com.ey.cpqcore.entity.MessageBackup;
import com.ey.cpqcore.event.SendMaterialPriceEvent;
import com.ey.cpqcore.utils.DateUtils;
import com.ey.cpqserver.message.constant.MsgTag;
import com.ey.cpqserver.message.constant.MsgTopic;
import lombok.extern.slf4j.Slf4j;
import org.apache.rocketmq.client.producer.SendResult;
import org.apache.rocketmq.client.producer.SendStatus;
import org.apache.rocketmq.spring.core.RocketMQTemplate;
import org.apache.rocketmq.spring.support.RocketMQHeaders;
import org.springframework.beans.BeanUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.event.EventListener;
import org.springframework.messaging.Message;
import org.springframework.messaging.support.MessageBuilder;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;

/**
 * 物料号价格推送RocketMq消息
 */
@Service
@Slf4j
public class SendMaterialPriceProducer {
    @Autowired
    private RocketMQTemplate rocketMQTemplate;

    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    /**
     * 事件驱动监听，接收SendMaterialPriceEvent发布事件，处理推送物料号价格到Mq
     * @param event
     */
    @EventListener
    public void buildAndSendMessage(SendMaterialPriceEvent event) {
        List<MaterialPrice> materialPrices = event.getMaterialPrices();
        if(CollUtil.isEmpty(materialPrices)) {
            log.info("SendMaterialPriceProducer 没有要发送的数据");
            return ;
        }
        //设置用户上下文
        if(event.getBaseUser() != null) {
            UserContext.setBaseUser(event.getBaseUser());
        }
        log.info("SendMaterialPriceProducer--user:{}",UserContext.getUser());
        for (MaterialPrice materialPrice : materialPrices) {
            SendMaterialPriceDTO dto = buildMsg(materialPrice);
            String key = materialPrice.getMaterialNumber()+"_"+materialPrice.getSalesType()+"_"+materialPrice.getCountryId();
            sendMsg(dto, key);
        }
    }

    /**
     * 发送消息到MQ
     * @param msgDto
     * @param key
     */
    private void sendMsg(SendMaterialPriceDTO msgDto, String key) {
        SendResult sendResult = null;
        String msgBody = JSONObject.toJSONString(msgDto);
        try {
            Message<?> message = MessageBuilder.withPayload(msgBody)
                    .setHeader(RocketMQHeaders.KEYS, key)
                    .build();
            sendResult = rocketMQTemplate.syncSend(MsgTopic.TOPIC_MATERIAL_PRICE+":"+MsgTag.CREATE,message);
            log.info("SendMaterialPriceProducer key:{},msgId：{}",key, sendResult.getMsgId());
        }catch (Exception e) {
            log.error("SendMaterialPriceProducer key:{},msgId：{},发送消息失败：{}", key, sendResult != null ? sendResult.getMsgId() : null, e.getMessage());
        }

    }

    /**
     * 实体转换，构建消息体
     * @param materialPrice
     * @return
     */
    private SendMaterialPriceDTO buildMsg(MaterialPrice materialPrice) {
        SendMaterialPriceDTO dto = SendMaterialPriceDTO.transferDto(materialPrice);
        dto.setEffectiveStartTime(DATE_FORMAT.format(DateUtil.beginOfDay(materialPrice.getEffectiveStartTime())));
        dto.setEffectiveEndTime(DATE_FORMAT.format(DateUtils.endOfDay(materialPrice.getEffectiveEndTime())));
        return dto;
    }


}

