package com.ey.cpqcore.dto.message;

import cn.hutool.core.bean.BeanUtil;
import com.ey.cpqcore.context.UserContext;
import com.ey.cpqcore.entity.MaterialPrice;
import com.ey.cpqcore.vo.UserAccountShowVO;
import lombok.Data;
import org.apache.commons.lang3.StringUtils;

import java.math.BigDecimal;
import java.util.Objects;

@Data
public class SendMaterialPriceDTO {
    /**
     * 出口类型,自营=self，供货=supply
     */
    private String exportType;
    /**
     * 销售模式供货=supply，买断=buyout，提佣=commission
     */
    private String salesType;
    /**
     * 物料号
     */
    private String matCd;
    /**
     * 国家ID
     */
    private String ctryId;
    /**
     * 币种
     */
    private String currencyId;
    /**
     * 指导价
     */
    private BigDecimal guidePrice;
    /**
     * 生效开始时间
     */
    private String effectiveStartTime;
    /**
     * 失效结束时间
     */
    private String effectiveEndTime;

    private String userId;

    private String employeeCode;

    private String employeeName;

    private String note;

    /**
     * 子公司ID
     */
    private String subsidiaryId;

    /**
     * 办事处ID
     */
    private String branchOfficeId;

    /**
     * 客户ID
     */
    private String customerId;

    /**
     * 自动核价单号
     */
    private String autoPriceNo;

    /**
     * 贸易术语
     */
    private String incotermsId;
    /**
     * 发货地/出发地代码
     */
    private String domesticFreightLandCode;
    /**
     * 起运港/起运站代码
     * 当出口类型：供货，不传
     * 当出口类型：自营，必传
     */
    private String domesticFreightPortCode;
    /**
     * 运输模式ID
     * 当出口类型：供货，不传
     * 当出口类型：自营，必传
     */
    private String transportTypeId;
    /**
     * 运输模式类型ID
     * 当运输模式为海运滚装散杂时，必传【滚装】或【散杂】
     */
    private String transportTypeRoleId;
    public static SendMaterialPriceDTO transferDto(MaterialPrice entity) {
        if (Objects.isNull(entity)) {
            return null;
        }
        SendMaterialPriceDTO dto = new SendMaterialPriceDTO();
        BeanUtil.copyProperties(entity, dto);
        UserAccountShowVO user = UserContext.getUser();
        dto.setUserId(user == null || user.getUserId() == null ?"选配模块":user.getUserId().toString());
        dto.setEmployeeCode(user == null || StringUtils.isBlank(user.getUserCode())?"选配模块":user.getUserCode());
        dto.setEmployeeName(user == null || StringUtils.isBlank(user.getUserName())?"选配模块":user.getUserName());
        dto.setNote("选配模块自动推送");
        dto.setMatCd(entity.getMaterialNumber());
        dto.setCtryId(entity.getCountryId());
        dto.setCurrencyId(entity.getCurrency());
        // 以EXW价格为基准，设置当前贸易术语对应的指导价
        BigDecimal guidePrice = entity.getExwPrice();
        if ("self".equals(entity.getExportType()) && "FOB".equals(entity.getIncotermsId()) && entity.getFobPrice() != null) {
            guidePrice = entity.getFobPrice();
        } else if ("self".equals(entity.getExportType()) && "DAP".equals(entity.getIncotermsId()) && entity.getDapPrice() != null) {
            guidePrice = entity.getDapPrice();
        }
        dto.setGuidePrice(guidePrice);

        // 供货场景不发送贸易术语相关字段；自营场景发送贸易术语、起运港和运输模式
        if ("self".equals(entity.getExportType())) {
            dto.setIncotermsId(entity.getIncotermsId());
            dto.setDomesticFreightPortCode(entity.getDomesticFreightPortCode());
            dto.setTransportTypeId(entity.getTransportTypeId());
            dto.setTransportTypeRoleId(entity.getTransportTypeRoleId());
        } else {
            dto.setIncotermsId(null);
            dto.setDomesticFreightPortCode(null);
            dto.setTransportTypeId(null);
            dto.setTransportTypeRoleId(null);
        }

        return dto;
    }

}

