import java.util.List;

/**
 * <p>
 *
 * </p>
 *
 * @author author
 * @since 2024年11月14日
 */
@Getter
@Setter
@Accessors(chain = true)
@TableName("cpq_material_price")
public class MaterialPrice implements Serializable {

    private static final long serialVersionUID = 1L;

    @TableId(value = "id", type = IdType.AUTO)
    private Long id;

    /**
     * 产品线id
     */
    @TableField("product_line_id")
    private String productLineId;

    @TableField("material_number")
    private String materialNumber;

    @TableField("country_id")
    private String countryId;

    @TableField("country_name")
    private String countryName;

    @TableField("solution_id")
    private String solutionId;

    @TableField("currency")
    private String currency;

    /**
     * 指导价
     */
    @TableField("exw_price")
    private BigDecimal exwPrice;

    /**
     * FOB价格
     */
    @TableField("fob_price")
    private BigDecimal fobPrice;

    /**
     * DAP价格
     */
    @TableField("dap_price")
    private BigDecimal dapPrice;

    /**
     * 贸易术语id
     */
    @TableField("incoterms_id")
    private String incotermsId;

    /**
     * 起运港/起运站代码
     */
    @TableField("domestic_freight_port_code")
    private String domesticFreightPortCode;

    /**
     * 运输模式ID
     */
    @TableField("transport_type_id")
    private String transportTypeId;

    /**
     * 运输模式类型ID
     */
    @TableField("transport_type_role_id")
    private String transportTypeRoleId;

    /**
     * 生效开始时间
     */
    @TableField("effective_start_time")
    private Date effectiveStartTime;

    /**
     * 生效结束时间
     */
    @TableField("effective_end_time")
    private Date effectiveEndTime;

    @TableField("model_id")
    private String modelId;


    /**
     * 销售类型
     * 买断：buyout
     * 提佣：commission
     * 供货：supply
     */
    @TableField("sales_type")
    private String salesType;

    /**
     * 出口类型
     * 自营：self
     * 供货：supply
     */
    @TableField("export_type")
    private String exportType;

    /**
     * 更新时间
     */
    @TableField(value = "updatedAt", fill = FieldFill.INSERT_UPDATE)
    private Date updatedAt;

    /**
     * 创建时间
     */
    @TableField(value = "createdAt", fill = FieldFill.INSERT)
    private Date createdAt;

    /**
     * 最后修改人
     */
    @TableField(value = "updatedBy", fill = FieldFill.INSERT_UPDATE)
    private String updatedBy;

    /**
     * 创建人
     */
    @TableField(value = "createdBy", fill = FieldFill.INSERT)
    private String createdBy;

    /**
     * 创建人名称
     */
    @TableField(value = "createdByName", fill = FieldFill.INSERT)
    private String createdByName;

    /**
     * 修改人名称
     */
    @TableField(value = "updatedByName", fill = FieldFill.INSERT_UPDATE)
    private String updatedByName;

    @TableField(exist = false)
    private List<MaterialPriceCalc> calcList;
}
